/* From Uiverse.io by ossoboy - Tags: button */
.__UIV_SCOPE__ button {
 background-color: rgb(82, 163, 255);
 color: transparent;
 border: 0 none;
 padding: 15px 30px;
 text-decoration: none;
 display: inline-block;
 transition: background-color 300ms ease, color 300ms ease;
 font-size: 17px;
 position: relative;
 text-align: center;
 cursor: pointer;
}

.__UIV_SCOPE__ button::before,
.__UIV_SCOPE__ button::after {
 content: attr(data-label);
 display: inline-block;
 position: absolute;
 transition: all 300ms ease;
 width: 100%;
 left: 0;
 top: 50%;
 color: white;
}

.__UIV_SCOPE__ button::before {
 opacity: 0;
 transform: translateY(calc(-50% - 15px));
}

.__UIV_SCOPE__ button::after {
 opacity: 1;
 transform: translateY(-50%);
}

.__UIV_SCOPE__ button:hover {
 background-color: rgb(66, 133, 209);
}

.__UIV_SCOPE__ button:hover::before {
 opacity: 1;
 transform: translateY(-50%);
}

.__UIV_SCOPE__ button:hover::after {
 opacity: 0;
 transform: translateY(calc(-50% + 15px));
}

.__UIV_SCOPE__ button:active {
 background-color: rgb(82, 163, 255);
}
